import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

import { useMediaQuery } from "@/registry/erbium/hooks/use-media-query";

export default function UseMediaQueryExample() {
  const reducedMotion = useMediaQuery("(prefers-reduced-motion: reduce)", {});

  return (
    <p aria-live="polite">
      Reduced motion: {reducedMotion ? "enabled" : "disabled"}. Change your system preference to
      update.
    </p>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import OverviewExample from "./variants/overview";



const meta = {
  parameters: {
    docs: { description: { component: "## Usage\n\nSubscribes to a CSS media query and updates when its match changes. This example tracks your system reduced motion preference.\n\nImport `useMediaQuery` from `@/registry/erbium/hooks/use-media-query`." } },
    layout: "centered",
  },
} satisfies Meta;

export default { ...meta, title: "Hooks/Use Media Query",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { useMediaQuery } from \"@/registry/erbium/hooks/use-media-query\";\n\nexport default function UseMediaQueryExample() {\n  const reducedMotion = useMediaQuery(\"(prefers-reduced-motion: reduce)\", {});\n\n  return (\n    <p aria-live=\"polite\">\n      Reduced motion: {reducedMotion ? \"enabled\" : \"disabled\"}. Change your system preference to\n      update.\n    </p>\n  );\n}\n" },
    },
  },
  render: OverviewExample,
};

import UseMediaQueryExample from "../examples/use-media-query-demo";

const Example = () => <UseMediaQueryExample />;

export default Example;
